// Exercise the actual browser client against HTTP, with no shared secret or browser credentials.
test('public dashboard client submits JSON without a key, password or authorization header', async () => {
	const {rpc} = await requestModule;
	const id = '00112233445566778899aabbccddeeff';
	const command = {op: 'settings', target: 'all', body: {sync: true}};
	let received;
	const server = http.createServer(async (request, response) => {
		response.setHeader('Content-Type', 'application/json');
		if (request.url === '/inter_comms/request') { response.end(JSON.stringify({id})); return; }
		if (request.url === '/inter_comms/rpc?id=' + id) {
			assert.equal(request.headers.authorization, undefined);
			assert.equal(request.headers.cookie, undefined);
			assert.equal(request.headers['content-type'], 'application/json');
			const chunks = []; for await (const chunk of request) chunks.push(chunk);
			received = JSON.parse(Buffer.concat(chunks)); response.writeHead(202); response.end(); return;
		}
		response.end(JSON.stringify({ok: true}));
	});
	await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
	try {
		assert.deepEqual(await rpc('http://127.0.0.1:' + server.address().port, command), {ok: true});
		assert.deepEqual(received, command);
	} finally { server.closeAllConnections(); await new Promise(resolve => server.close(resolve)); }
});

// Verify visibility at the hardware-count boundary and when leadership or peer identification changes.
test('device overview requires a master and two physical devices, excluding simulated and unknown peers', async () => {
	const {deviceOverview} = await import(pathToFileURL(path.join(moduleDirectory, '../inter_comms_ui/web/devices.js')).href);
	const hardware = id => ({id, version: '17.0.0', simulated: false});
	const simulator = {id: 'sim', version: '17.0.0 (sim)', simulated: true};
	assert.equal(deviceOverview({master: true, devices: [hardware('one')]}).visible, false);
	assert.equal(deviceOverview({master: true, devices: [hardware('one'), simulator]}).visible, false);
	assert.equal(deviceOverview({master: true, devices: [simulator]}).visible, false);
	assert.equal(deviceOverview({master: false, devices: [hardware('one'), hardware('two')]}).visible, false);
	const visible = deviceOverview({master: true, devices: [hardware('one'), hardware('two'), simulator]});
	assert.equal(visible.visible, true);
	assert.deepEqual(visible.physicalDevices.map(device => device.id), ['one', 'two']);
	assert.equal(deviceOverview({master: true, devices: [hardware('one'), {version: '17.0.0 (sim)'}]}).visible, false);
	assert.equal(deviceOverview({master: true, devices: [hardware('one'), {version: ''}]}).visible, false);
	assert.equal(deviceOverview({master: true, devices: [hardware('one'), {version: '17.0.0'}]}).visible, true);
	assert.equal(deviceOverview({master: true, devices: [hardware('one'), {...hardware('two'), online: false}]}).visible, false);
	assert.equal(deviceOverview({}).visible, false);
});

// Compile the actual metadata helper with poisoned automatic storage so uninitialized tails fail deterministically.
test('OTA release metadata strings terminate at the copied length, not at the fixed field width', () => {
	const source = readFileSync(path.resolve(moduleDirectory, '../../wled00/wled_metadata.cpp'), 'utf8');
	const start = source.indexOf('template<size_t len>');
	const end = source.indexOf('\n/**', start);
	assert.ok(start >= 0 && end > start);
	const directory = mkdtempSync(path.join(tmpdir(), 'wled-metadata-'));
	try {
		const program = '#include <string>\n#include <cstring>\n#include <cassert>\nusing String=std::string;\n' + source.slice(start, end) + `
int main() {
  const char release[48] = "ESP32-C6_8MB";
  const char other[48] = "Different_release";
  const char empty[48] = {};
  char full[48]; memset(full, 'x', sizeof(full));
  assert(bufToString(release) == "ESP32-C6_8MB");
  assert(bufToString(release) == bufToString(release));
  assert(bufToString(other) != bufToString(release));
  assert(bufToString(empty).empty());
  assert(bufToString(full) == std::string(48, 'x'));
}
`;
		writeFileSync(path.join(directory, 'metadata.cpp'), program);
		execFileSync('c++', ['-std=c++11', '-ftrivial-auto-var-init=pattern', path.join(directory, 'metadata.cpp'), '-o', path.join(directory, 'metadata')]);
		execFileSync(path.join(directory, 'metadata'));
	} finally { rmSync(directory, {recursive: true, force: true}); }
});

test('firmware status distinguishes progress, legacy telemetry and persistent errors', async () => {
	const {firmwareState} = await import(pathToFileURL(path.join(moduleDirectory, '../inter_comms_ui/web/updates.js')).href);
	const progress = firmwareState({updateState: 'downloading', updateOffset: 768, updateSize: 1536, updateTelemetry: true, result: 'Downloading firmware'});
	assert.match(progress.label, /Transferring.*50%.*768\/1536/);
	assert.equal(firmwareState({updateState: 'error', result: 'Firmware SHA-256 mismatch', commandResult: 'Applied'}).detail, 'Firmware SHA-256 mismatch');
	assert.match(firmwareState({updateState: 'queued', updateTelemetry: false}).detail, /Older firmware does not report byte progress/);
	assert.equal(firmwareState({updateState: 'complete'}).label, 'Build verified after reboot');
});

test('actual C++ protocol rejects replay, stale challenges and malformed frames and elects a live master', () => {
	const directory = mkdtempSync(path.join(tmpdir(), 'inter-comms-protocol-'));
	try {
		const executable = path.join(directory, 'protocol-test');
		execFileSync('c++', ['-std=c++11', '-Wall', '-Wextra', '-Werror', '-fsanitize=address,undefined', '-fno-omit-frame-pointer', path.join(__dirname, 'protocol_test.cpp'), '-o', executable]);
		execFileSync(executable, [], {timeout: 30000});
	} finally { rmSync(directory, {recursive: true, force: true}); }
});

test('provisioning generates private, reusable independent keys and refuses accidental replacement', () => {
	const directory = mkdtempSync(path.join(tmpdir(), 'inter-comms-keys-'));
	try {
		const script = path.join(moduleDirectory, 'provision.py');
		execFileSync('python3', [script, '--output-dir', directory]);
		const credentialsPath = path.join(directory, 'private_credentials.json');
		const credentials = JSON.parse(readFileSync(credentialsPath));
		assert.match(credentials.groupKey, /^[0-9a-f]{64}$/); assert.match(credentials.adminKey, /^[0-9a-f]{64}$/);
		assert.notEqual(credentials.groupKey, credentials.adminKey);
		assert.equal(statSync(credentialsPath).mode & 0o777, 0o600);
		assert.equal(statSync(path.join(directory, 'group_keys.h')).mode & 0o777, 0o600);
		assert.throws(() => execFileSync('python3', [script, '--output-dir', directory], {stdio: 'pipe'}));
		const imported = path.join(directory, 'imported');
		execFileSync('python3', [script, '--output-dir', imported, '--import-credentials', credentialsPath]);
		assert.equal(readFileSync(path.join(directory, 'group_keys.h'), 'utf8'), readFileSync(path.join(imported, 'group_keys.h'), 'utf8'));
	} finally { rmSync(directory, {recursive: true, force: true}); }
});
